import math
import pyomo.environ as pyo

# All numeric constants live here.
DATA = {
    "surface_area": 50.0,      # total surface area incl. top and bottom
    "n_points": 41,            # number of radius candidates on the grid
    "r_min": 0.05,             # smallest radius considered
    "r_max": 2.49,             # largest radius considered (so h >= 0)
    "pi": math.pi,             # pi
}


def build_model(data=None):
    d = data or DATA
    S = d["surface_area"]
    N = d["n_points"]
    r_min = d["r_min"]
    r_max = d["r_max"]
    PI = d["pi"]

    model = pyo.ConcreteModel()

    model.I = pyo.RangeSet(0, N - 1)

    # Pre-computed corner data: radius r_i, implied height h_i, induced volume v_i
    r_pts = {}
    h_pts = {}
    v_pts = {}
    for i in model.I:
        if N == 1:
            r_i = r_max
        else:
            r_i = r_min + (r_max - r_min) * i / (N - 1)
        # surface area forces: 2*pi*r*h + 2*pi*r^2 = S
        h_i = (S - 2.0 * PI * r_i * r_i) / (2.0 * PI * r_i)
        if h_i < 0.0:
            h_i = 0.0
        v_i = PI * r_i * r_i * h_i
        r_pts[i] = r_i
        h_pts[i] = h_i
        v_pts[i] = v_i

    # one-hot selection of a radius candidate
    model.x = pyo.Var(model.I, within=pyo.Binary)

    bigM_r = r_max + 1.0
    bigM_h = max(h_pts.values()) + 1.0
    bigM_v = max(v_pts.values()) + 1.0
    bigM_ratio = bigM_h / max(r_min, 1e-6) + 1.0

    # achieved radius, height, volume, and ratio
    model.r = pyo.Var(within=pyo.NonNegativeReals, bounds=(0.0, bigM_r))
    model.h = pyo.Var(within=pyo.NonNegativeReals, bounds=(0.0, bigM_h))
    model.v = pyo.Var(within=pyo.NonNegativeReals, bounds=(0.0, bigM_v))
    model.ratio = pyo.Var(within=pyo.Reals, bounds=(-bigM_ratio, bigM_ratio))

    # exactly one radius candidate chosen
    def pick_rule(m):
        return sum(m.x[i] for i in m.I) == 1
    model.pick_one = pyo.Constraint(rule=pick_rule)

    # radius forced to the chosen candidate
    def r_hi_rule(m, i):
        return m.r - r_pts[i] <= bigM_r * (1 - m.x[i])
    model.r_hi = pyo.Constraint(model.I, rule=r_hi_rule)

    def r_lo_rule(m, i):
        return r_pts[i] - m.r <= bigM_r * (1 - m.x[i])
    model.r_lo = pyo.Constraint(model.I, rule=r_lo_rule)

    # height forced to the chosen candidate's implied height
    def h_hi_rule(m, i):
        return m.h - h_pts[i] <= bigM_h * (1 - m.x[i])
    model.h_hi = pyo.Constraint(model.I, rule=h_hi_rule)

    def h_lo_rule(m, i):
        return h_pts[i] - m.h <= bigM_h * (1 - m.x[i])
    model.h_lo = pyo.Constraint(model.I, rule=h_lo_rule)

    # volume forced to the chosen candidate's induced volume
    def v_hi_rule(m, i):
        return m.v - v_pts[i] <= bigM_v * (1 - m.x[i])
    model.v_hi = pyo.Constraint(model.I, rule=v_hi_rule)

    def v_lo_rule(m, i):
        return v_pts[i] - m.v <= bigM_v * (1 - m.x[i])
    model.v_lo = pyo.Constraint(model.I, rule=v_lo_rule)

    # ratio forced to the chosen candidate's height-to-radius ratio
    def ratio_hi_rule(m, i):
        return m.ratio - (h_pts[i] / r_pts[i]) <= bigM_ratio * (1 - m.x[i])
    model.ratio_hi = pyo.Constraint(model.I, rule=ratio_hi_rule)

    def ratio_lo_rule(m, i):
        return (h_pts[i] / r_pts[i]) - m.ratio <= bigM_ratio * (1 - m.x[i])
    model.ratio_lo = pyo.Constraint(model.I, rule=ratio_lo_rule)

    # exact surface-area predicate for the chosen corner (constants, so linear)
    def surface_rule(m):
        return sum(
            (2.0 * PI * r_pts[i] * h_pts[i] + 2.0 * PI * r_pts[i] * r_pts[i]) * m.x[i]
            for i in m.I
        ) == S
    model.surface = pyo.Constraint(rule=surface_rule)

    # maximize volume
    def obj_rule(m):
        return m.v
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    return model


